function RuntimeProviderSetup(){
 const [key,setKey]=useState(''),[model,setModel]=useState(''),[budget,setBudget]=useState(1),[pending,setPending]=useState(false),[note,setNote]=useState('');
 const configure=async(provider:'codex'|'claude-api')=>{if(pending)return;setPending(true);const requestId=crypto.randomUUID();try{const result=await window.capri?.agency?.('runtimeAgents',{requestId,provider,...(provider==='claude-api'?{apiKey:key,model,budgetUsd:budget}:{})});if(result?.requestId!==requestId||result.saved!==true)throw Error('Configuration was not confirmed. Your draft is retained.');if(provider==='claude-api')setKey('');setNote('Configuration saved. Enable the provider and grant a task separately. Codex requires manual sign-in to its isolated profile.');}catch{setNote('Configuration was not confirmed. Your draft is retained.');}finally{setPending(false);}};
 return <section className="card section-card"><h2>Runtime agent connections</h2><p>Connections remain disabled until enabled and granted to a task. Each delegate works in an isolated project snapshot.</p><button className="secondary" disabled={pending} onClick={()=>void configure('codex')}>Choose Codex executable</button><label>Claude API key<input type="password" autoComplete="off" value={key} onChange={event=>setKey(event.target.value)}/></label><label>Claude model<input value={model} onChange={event=>setModel(event.target.value)}/></label><label>Maximum cost per delegated task ($)<input type="number" min="0.01" max="100" step="0.01" value={budget} onChange={event=>setBudget(Number(event.target.value))}/></label><button className="secondary" disabled={pending||!key||!model} onClick={()=>void configure('claude-api')}>Save Claude connection</button>{note&&<p role="status">{note}</p>}</section>;
}
